const config = require(\"../config\");
const partner = require(\"../partner\");

const RATE_LIMIT_PER_SEC = 5;
const recentSends = [];

async function reserveSlot() {
  for (;;) {
    const now = Date.now();
    while (recentSends.length && now - recentSends[0] >= 1000) recentSends.shift();
    if (recentSends.length < RATE_LIMIT_PER_SEC) {
      recentSends.push(now);
      return;
    }
    await new Promise((resolve) => setTimeout(resolve, recentSends[0] + 1000 - now));
  }
}

async function send({ notificationId, userId, message }) {
  await reserveSlot();
  return partner.request(\"/v1/notifications\", {
    method: \"POST\",
    body: { notificationId, userId, message },
    headers: { authorization: \"Bearer \" + config.paymentApiKey },
  });
}

module.exports = { send };
EOF
