const { Queue } = require(\"bullmq\");
const IORedis = require(\"ioredis\");
(async () => {
  const conn = new IORedis(process.env.REDIS_URL, { maxRetriesPerRequest: null });
  const jobs = new Queue(\"jobs\", { connection: conn });
  const dlq = new Queue(\"jobs-dlq\", { connection: conn });
  const dead = await dlq.getJobs([\"waiting\"], 0, -1);
  let moved = 0;
  for (const d of dead) {
    const { error, ...data } = d.data;
    const old = await jobs.getJob(d.id);
    if (old) await old.remove();
    await jobs.add(d.name, data, { jobId: d.id, attempts: 5, backoff: { type: \"exponential\", delay: 1000 }, removeOnComplete: 5000 });
    await d.remove();
    moved++;
  }
  console.log(\"requeued\", moved, \"of\", dead.length, \"dead-lettered jobs\");
  await jobs.close(); await dlq.close(); await conn.quit();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
