  const { rows: orders } = await pool.query(
    "SELECT sku, amount_cents FROM orders WHERE account_id = $1 ORDER BY created_at DESC LIMIT 100",
    [accountId]
  );
  const html = render(accounts[0], orders, month);
  remember(key, html);
  return html;
}

module.exports = { statementFor };
EOF
