const { Queue } = require(\"bullmq\");
const IORedis = require(\"ioredis\");
const config = require(\"./config\");

const RATE_LIMIT_BASE_MS = 1000;
const RATE_LIMIT_MAX_MS = 60000;

function backoffStrategy(attemptsMade, type, err) {
  if (type "'!== "partner") return 200;
  if (!err || err.status !== 429) return 200;
  const exponential = Math.min(RATE_LIMIT_MAX_MS, RATE_LIMIT_BASE_MS * 2 ** (attemptsMade - 1));
  const retryAfterMs = (err.retryAfterSec || 0) * 1000;
  const delay = Math.max(retryAfterMs, exponential);
  return Math.floor(delay * (0.8 + Math.random() * 0.4));
}

const connection = new IORedis(config.redisUrl, { maxRetriesPerRequest: null });
const jobs = new Queue("jobs", { connection, settings: { backoffStrategy } });
const deadLetters = new Queue("jobs-dlq", { connection });

const JOB_OPTIONS = { attempts: 3, backoff: { type: "fixed", delay: 200 }, removeOnComplete: 5000 };
const NOTIFICATION_OPTIONS = { attempts: 8, backoff: { type: "partner" }, removeOnComplete: 5000 };
const OPTIONS_BY_JOB = { notification: NOTIFICATION_OPTIONS };

async function enqueue(name, data, id) {
  await jobs.add(name, data, { ...(OPTIONS_BY_JOB[name] || JOB_OPTIONS), jobId: id });
}

module.exports = { connection, jobs, deadLetters, enqueue };
EOF
