const config = require(\"../config\");
const partner = require(\"../partner\");
const catalog = require(\"./catalog\");
const logger = require(\"../logger\");
const { connection } = require(\"../queue\");

const PRICE_TTL_SEC = 60;
const PRICING_MAX_WAIT_MS = 5000;
const inflight = new Map();

async function fetchPartnerPrice(sku) {
  const key = "'`price:${sku}`;
  const cached = await connection.get(key);
  if (cached !== null) return Number(cached);
  const data = await partner.request(`/v1/prices/${encodeURIComponent(sku)}`, {
    timeoutMs: Math.min(config.downstreamTimeoutMs, PRICING_MAX_WAIT_MS),
  });
  await connection.set(key, data.priceCents, "EX", PRICE_TTL_SEC);
  return data.priceCents;
}

function priceFor(sku) {
  let pending = inflight.get(sku);
  if (!pending) {
    pending = fetchPartnerPrice(sku).finally(() => inflight.delete(sku));
    inflight.set(sku, pending);
  }
  return pending.catch((err) => {
    logger.warn("pricing unavailable, using list price", { sku, reason: err.name === "AbortError" ? "timeout" : err.message });
    return catalog.listPrice(sku);
  });
}

module.exports = { priceFor };
EOF
